class CheckerboardZoneControlWin(WinCondition):
    """
    Exploits the diagonal-only neighborhood's natural checkerboard partition.
    The board is split into two independent sub-grids (even-parity cells where
    (r+c)%2==0, and odd-parity cells where (r+c)%2==1). The player wins by
    fully clearing (revealing all safe cells in) EITHER sub-grid. A skilled
    solver can recognize which sub-grid is safer, deduce mine locations within
    one partition using diagonal clues, and focus effort there. Random play
    spreads clicks across both grids indiscriminately and rarely completes
    either one.
    """

    def evaluate(self, board, game, action):
        rows = board.config.rows
        cols = board.config.cols

        for parity in (0, 1):
            total_safe = 0
            revealed_safe = 0
            for r in range(rows):
                for c in range(cols):
                    if (r + c) % 2 != parity:
                        continue
                    cell = board.grid[r][c]
                    if not cell.is_mine:
                        total_safe += 1
                        if cell.is_revealed:
                            revealed_safe += 1
            if total_safe > 0 and revealed_safe >= total_safe:
                return "won"

        return None

    def summary(self):
        return {"mechanic": "clear-either-checkerboard-subgrid"}

