class SectorSumInfo(InfoStrategy):
    """
    Instead of showing the total adjacent mine count, each revealed cell
    displays two digits: the mine count in its 'northern' neighbors (rows
    above) and its 'southern' neighbors (rows below), separated by a slash.
    This splits the single clue into two directional partial counts, giving
    a skilled solver richer triangulation constraints (north vs south mine
    distribution) while a random agent cannot exploit the extra structure.
    Cells with no neighbors in a direction show '0' for that sector.
    Zero-zero cells render as blank.
    """

    def encode(self, board, r, c):
        north = 0
        south = 0
        for nr, nc in board.neighbors(r, c):
            if board.grid[nr][nc].is_mine:
                if nr < r:
                    north += 1
                elif nr > r:
                    south += 1
                # same row mines go to neither sector (east/west omitted)
        if north == 0 and south == 0:
            return ""
        return str(north) + "/" + str(south)

    def summary(self):
        return {
            "encoding": "north_mines/south_mines",
            "note": "Splits adjacent mine count into above-row vs below-row sectors; same-row neighbors excluded from display but still affect board logic"
        }

