class NorthSouthSplitPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed or cell.is_mine:
            return None
        raw = cell.adjacent_mines
        if isinstance(raw, str):
            raw_str = raw.strip()
            if not raw_str or raw_str == '':
                return 0
            if '/' in raw_str:
                parts = raw_str.split('/')
                try:
                    north = int(parts[0])
                    south = int(parts[1])
                    return north + south
                except (ValueError, IndexError):
                    return 0
            try:
                return int(raw_str)
            except ValueError:
                return 0
        if raw is None:
            return 0
        return int(raw)

    def neighbor_positions(self, game, r, c, rows, cols):
        return [(nr, nc) for nr, nc in game.board.neighbors(r, c)]

class VonNeumannDirectionalAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed or cell.is_mine:
            return None
        raw = cell.adjacent_mines
        if isinstance(raw, str):
            digits = ''.join(ch for ch in raw if ch.isdigit())
            if digits:
                return int(digits)
            return 0
        if raw is None:
            return None
        return int(raw)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        direction_map = {
            'N': (-1, 0), 'S': (1, 0), 'E': (0, 1), 'W': (0, -1),
            'NE': (-1, 1), 'NW': (-1, -1), 'SE': (1, 1), 'SW': (1, -1)
        }
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if not cell.is_revealed or cell.is_mine:
                    continue
                raw = cell.adjacent_mines
                if not isinstance(raw, str) or not raw:
                    continue
                digits = ''.join(ch for ch in raw if ch.isdigit())
                if not digits:
                    continue
                label = raw[:-len(digits)] if digits else raw
                if label not in direction_map:
                    continue
                dr, dc = direction_map[label]
                neighbors = game.board.neighbors(r, c)
                unrevealed = [
                    (nr, nc) for nr, nc in neighbors
                    if not game.get_cell(nr, nc).is_revealed and (nr, nc) not in mine_set
                ]
                if not unrevealed:
                    continue
                for nr, nc in unrevealed:
                    vr = nr - r
                    vc = nc - c
                    alignment = vr * dr + vc * dc
                    if alignment > 0:
                        current = prob_map.get((nr, nc), 0.5)
                        prob_map[(nr, nc)] = min(1.0, current * 1.25)
                    elif alignment < 0:
                        current = prob_map.get((nr, nc), 0.5)
                        prob_map[(nr, nc)] = max(0.0, current * 0.75)
        total = sum(prob_map.values())
        if total > 0:
            remaining_mines = game.get_config().mine_count - len(mine_set)
            scale = remaining_mines / total if total > 0 else 1.0
            if 0.5 <= scale <= 2.0:
                prob_map = {k: min(1.0, v * scale) for k, v in prob_map.items()}
        return prob_map

class ZoneControlFocusedAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)

    def _zone_control_score(self, game, r, c):
        rows = 16
        cols = 16
        zone_height = 4
        zone_width = 4
        zr = r // zone_height
        zc = c // zone_width
        r_start = zr * zone_height
        c_start = zc * zone_width
        total_safe = 0
        revealed_safe = 0
        for rr in range(r_start, r_start + zone_height):
            for cc in range(c_start, c_start + zone_width):
                cell = game.get_cell(rr, cc)
                if not cell.is_mine:
                    total_safe += 1
                    if cell.is_revealed:
                        revealed_safe += 1
        if total_safe == 0:
            return (True, 0.0)
        already_controlled = revealed_safe * 2 > total_safe
        needed = (total_safe // 2 + 1) - revealed_safe
        unrevealed_safe = total_safe - revealed_safe
        if needed <= 0:
            progress = 1.0
        elif unrevealed_safe <= 0:
            progress = 0.0
        else:
            progress = 1.0 - (needed / unrevealed_safe)
        return (already_controlled, progress)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        already_controlled, progress = self._zone_control_score(game, r, c)
        if already_controlled:
            zone_bonus = -0.1
        else:
            zone_bonus = -progress * 0.3
        return (p + zone_bonus, self._rng.random())

class ParityAwareMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        return None

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        changed = True
        iterations = 0
        while changed and iterations < 10:
            changed = False
            iterations += 1
            for r in range(rows):
                for c in range(cols):
                    cell = grid[r][c]
                    if not cell.is_revealed:
                        continue
                    true_count = cell.adjacent_mines
                    parity = true_count % 2
                    nbrs = neighbors_of.get((r, c), [])
                    known_mine_count = sum(
                        1 for nr, nc in nbrs
                        if (nr, nc) in mine_set or grid[nr][nc].is_flagged
                    )
                    unknown_nbrs = [
                        (nr, nc) for nr, nc in nbrs
                        if not grid[nr][nc].is_revealed
                        and (nr, nc) not in mine_set
                        and not grid[nr][nc].is_flagged
                    ]
                    if len(unknown_nbrs) == 0:
                        continue
                    remaining_parity = (parity - known_mine_count % 2) % 2
                    if len(unknown_nbrs) == 1:
                        pos = unknown_nbrs[0]
                        if remaining_parity == 1:
                            if pos not in mine_set:
                                mine_set.add(pos)
                                prob_map[pos] = 1.0
                                changed = True
                        else:
                            if prob_map.get(pos, 0.5) > 0.0:
                                prob_map[pos] = 0.0
                                changed = True
                    else:
                        certain_mines = [p for p in unknown_nbrs if prob_map.get(p, 0.5) >= 1.0]
                        certain_safes = [p for p in unknown_nbrs if prob_map.get(p, 0.5) <= 0.0]
                        truly_unknown = [
                            p for p in unknown_nbrs
                            if prob_map.get(p, 0.5) > 0.0 and prob_map.get(p, 0.5) < 1.0
                        ]
                        fixed_mine_parity = (len(certain_mines)) % 2
                        needed_parity = (remaining_parity - fixed_mine_parity) % 2
                        if len(truly_unknown) == 1:
                            pos = truly_unknown[0]
                            if needed_parity == 1:
                                if pos not in mine_set:
                                    mine_set.add(pos)
                                    prob_map[pos] = 1.0
                                    changed = True
                            else:
                                if prob_map.get(pos, 0.5) > 0.0:
                                    prob_map[pos] = 0.0
                                    changed = True
        return prob_map

class DriftingMinesFlagFirstAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
