class RingNeighborhoodZoneCaptureAgent(ArchiveAwarePAFGAgent):

    def __init__(self, seed=None):
        super().__init__(seed=seed)
        self._ring_offsets = [
            (-2, -2), (-2, -1), (-2, 0), (-2, -1+2), (-2, 2),
            (-1, -2), (-1, 2),
            (0, -2), (0, 2),
            (1, -2), (1, 2),
            (2, -2), (2, -1), (2, 0), (2, 1), (2, 2),
        ]

    def neighbor_positions(self, game, r, c, rows, cols):
        result = []
        for dr, dc in self._ring_offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc))
        return result

    def _zone_capture_score(self, game, rows, cols):
        zone_row_size = rows / 4
        zone_col_size = cols / 4
        scores = {}
        for zr in range(4):
            for zc in range(4):
                r_start = int(zr * zone_row_size)
                r_end = int((zr + 1) * zone_row_size)
                c_start = int(zc * zone_col_size)
                c_end = int((zc + 1) * zone_col_size)
                total_safe = 0
                revealed_safe = 0
                for r in range(r_start, r_end):
                    for c in range(c_start, c_end):
                        cell = game.get_cell(r, c)
                        if not cell.is_mine:
                            total_safe += 1
                            if cell.is_revealed:
                                revealed_safe += 1
                if total_safe == 0:
                    ratio = 1.0
                else:
                    ratio = revealed_safe / total_safe
                for r in range(r_start, r_end):
                    for c in range(c_start, c_end):
                        scores[(r, c)] = ratio
        return scores

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        p = prob_map.get(pos, 0.5)
        zone_scores = self._zone_capture_score(game, rows, cols)
        zone_ratio = zone_scores.get(pos, 1.0)
        zone_bonus = (1.0 - zone_ratio) * 0.15
        adjusted_p = p - zone_bonus
        return (adjusted_p, self._rng.random())

