class ProgressiveZoneWin(WinCondition):
    """
    The board is divided into a 4x4 grid of zones (each 4x4 cells on a 16x16
    board). The player wins by fully clearing (revealing all safe cells in)
    any 6 out of 16 zones. This rewards a skilled solver who can deduce safe
    cells within targeted zones and focus effort efficiently, while random
    play scatters clicks and rarely completes even a single zone.
    """

    ZONES_ROWS = 4
    ZONES_COLS = 4
    ZONES_NEEDED = 6

    def __init__(self, seed=None):
        super().__init__(seed)

    def summary(self):
        return {
            "zones_rows": self.ZONES_ROWS,
            "zones_cols": self.ZONES_COLS,
            "zones_needed": self.ZONES_NEEDED,
        }

    def evaluate(self, board, game, action):
        rows = board.config.rows
        cols = board.config.cols
        zone_h = rows // self.ZONES_ROWS
        zone_w = cols // self.ZONES_COLS

        cleared_zones = 0

        for zr in range(self.ZONES_ROWS):
            for zc in range(self.ZONES_COLS):
                r_start = zr * zone_h
                r_end = r_start + zone_h
                c_start = zc * zone_w
                c_end = c_start + zone_w

                zone_safe_total = 0
                zone_safe_revealed = 0

                for r in range(r_start, r_end):
                    for c in range(c_start, c_end):
                        cell = board.grid[r][c]
                        if not cell.is_mine:
                            zone_safe_total += 1
                            if cell.is_revealed:
                                zone_safe_revealed += 1

                if zone_safe_total > 0 and zone_safe_revealed == zone_safe_total:
                    cleared_zones += 1

        if cleared_zones >= self.ZONES_NEEDED:
            return "won"
        return None

