class ZoneFocusedMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)
        self._zone_h = 4
        self._zone_w = 4
        self._zones_needed = 6

    def _zone_of(self, r, c):
        return (r // self._zone_h, c // self._zone_w)

    def _zone_score(self, game, grid, rows, cols):
        scores = {}
        for zr in range(4):
            for zc in range(4):
                r_start = zr * self._zone_h
                c_start = zc * self._zone_w
                total_safe = 0
                revealed_safe = 0
                unrevealed_safe = 0
                for r in range(r_start, r_start + self._zone_h):
                    for c in range(c_start, c_start + self._zone_w):
                        cell = game.get_cell(r, c)
                        if not cell.is_mine:
                            total_safe += 1
                            if cell.is_revealed:
                                revealed_safe += 1
                            else:
                                unrevealed_safe += 1
                if total_safe == 0:
                    scores[(zr, zc)] = (False, 0.0)
                elif unrevealed_safe == 0:
                    scores[(zr, zc)] = (True, 1.0)
                else:
                    scores[(zr, zc)] = (False, revealed_safe / total_safe)
        return scores

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        zone_scores = self._zone_score(game, grid, rows, cols)
        zr, zc = self._zone_of(r, c)
        zone_info = zone_scores.get((zr, zc), (False, 0.0))
        already_cleared, completion_ratio = zone_info
        if already_cleared:
            zone_bonus = 0.0
        else:
            zone_bonus = completion_ratio
        adjusted_p = p - 0.3 * zone_bonus
        return (adjusted_p, -zone_bonus, self._rng.random())

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        zone_scores = self._zone_score(game, grid, rows, cols)
        cleared_count = sum(1 for v in zone_scores.values() if v[0])
        if cleared_count >= self._zones_needed:
            return prob_map
        best_zones = sorted(
            [(ratio, zr, zc) for (zr, zc), (cleared, ratio) in zone_scores.items() if not cleared],
            reverse=True
        )
        top_zones = set()
        for ratio, zr, zc in best_zones[:max(1, self._zones_needed - cleared_count)]:
            top_zones.add((zr, zc))
        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            zone = self._zone_of(r, c)
            if zone in top_zones:
                adjusted[pos] = p * 0.85
            else:
                adjusted[pos] = p
        return adjusted

class NoisyCountMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        true_count = cell.adjacent_mines
        return true_count

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        lie_prob = 0.20
        shrink = 1.0 - lie_prob
        adjusted = {}
        for pos, p in prob_map.items():
            pulled = 0.5 + shrink * (p - 0.5)
            adjusted[pos] = pulled
        return adjusted

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        noise_penalty = abs(p - 0.5) * 0.1
        safe_score = p + noise_penalty
        return (safe_score, self._rng.random())

