class RippleReveal(RevealStrategy):
    """Cascade reveal that expands in concentric rings (BFS by distance from click),
    but stops the flood-fill at the boundary of each ring if any mine-adjacent cell
    is found in that ring — giving skilled solvers a distance-layered constraint
    structure while random play cannot exploit the ring-stop information."""

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        if cell.is_mine or cell.is_revealed or cell.is_flagged:
            return []

        # If the clicked cell itself is numbered, reveal only it
        if cell.adjacent_mines > 0:
            cell.is_revealed = True
            return [(r, c)]

        # BFS by ring distance; stop expanding a ring if it contains any numbered cell
        revealed: list[tuple[int, int]] = []
        visited: set[tuple[int, int]] = {(r, c)}

        current_ring: list[tuple[int, int]] = [(r, c)]

        while current_ring:
            # Reveal all cells in the current ring
            ring_revealed: list[tuple[int, int]] = []
            for cr, cc in current_ring:
                curr = board.grid[cr][cc]
                if curr.is_mine or curr.is_flagged:
                    continue
                if not curr.is_revealed:
                    curr.is_revealed = True
                    ring_revealed.append((cr, cc))

            revealed.extend(ring_revealed)

            # Check if any newly revealed cell in this ring is numbered
            # If so, stop expanding — the ripple halts at this boundary
            ring_has_numbered = any(
                board.grid[cr][cc].adjacent_mines > 0
                for cr, cc in ring_revealed
            )
            if ring_has_numbered:
                break

            # Build next ring: neighbors of all zero-cells revealed this ring
            next_ring: list[tuple[int, int]] = []
            for cr, cc in ring_revealed:
                if board.grid[cr][cc].adjacent_mines == 0:
                    for nr, nc in board.neighbors(cr, cc):
                        if (nr, nc) not in visited:
                            nb = board.grid[nr][nc]
                            if not nb.is_mine and not nb.is_flagged and not nb.is_revealed:
                                visited.add((nr, nc))
                                next_ring.append((nr, nc))

            current_ring = next_ring

        return revealed

