class RippleRingBoundaryAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        numbered_revealed = set()
        for rr in range(rows):
            for cc in range(cols):
                cell = grid[rr][cc]
                if cell.is_revealed and not cell.is_mine and cell.adjacent_mines > 0:
                    numbered_revealed.add((rr, cc))

        ring_boundary_unrevealed = set()
        for (rr, cc) in numbered_revealed:
            for (nr, nc) in neighbors_of.get((rr, cc), game.board.neighbors(rr, cc)):
                ncell = grid[nr][nc]
                if not ncell.is_revealed and not ncell.is_flagged:
                    ring_boundary_unrevealed.add((nr, nc))

        if not ring_boundary_unrevealed:
            return prob_map

        zero_revealed = set()
        for rr in range(rows):
            for cc in range(cols):
                cell = grid[rr][cc]
                if cell.is_revealed and not cell.is_mine and cell.adjacent_mines == 0:
                    zero_revealed.add((rr, cc))

        deep_unrevealed = set()
        for (rr, cc) in zero_revealed:
            for (nr, nc) in neighbors_of.get((rr, cc), game.board.neighbors(rr, cc)):
                ncell = grid[nr][nc]
                if not ncell.is_revealed and not ncell.is_flagged:
                    if (nr, nc) not in ring_boundary_unrevealed:
                        deep_unrevealed.add((nr, nc))

        new_map = dict(prob_map)

        for pos in ring_boundary_unrevealed:
            if pos in new_map and pos not in mine_set:
                new_map[pos] = min(1.0, new_map[pos] * 1.25)

        for pos in deep_unrevealed:
            if pos in new_map and pos not in mine_set:
                new_map[pos] = max(0.0, new_map[pos] * 0.85)

        return new_map

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        nbs = neighbors_of.get((r, c), game.board.neighbors(r, c))
        revealed_numbered_neighbors = sum(
            1 for nr, nc in nbs
            if grid[nr][nc].is_revealed and grid[nr][nc].adjacent_mines > 0
        )
        boundary_penalty = 0.08 * revealed_numbered_neighbors
        adjusted = min(1.0, p + boundary_penalty)
        return (adjusted, -revealed_numbered_neighbors, self._rng.random())

class DirectionalTriangulationAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "reveal-first"

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        zone_h = rows // 4
        zone_w = cols // 4

        zone_safe_total = {}
        zone_safe_revealed = {}

        for zr in range(4):
            for zc in range(4):
                key = (zr, zc)
                zone_safe_total[key] = 0
                zone_safe_revealed[key] = 0
                for r in range(zr * zone_h, min((zr + 1) * zone_h, rows)):
                    for c in range(zc * zone_w, min((zc + 1) * zone_w, cols)):
                        cell = grid[r][c]
                        if not cell.is_mine:
                            zone_safe_total[key] += 1
                            if cell.is_revealed:
                                zone_safe_revealed[key] += 1

        zone_remaining = {}
        for key in zone_safe_total:
            total = zone_safe_total[key]
            revealed = zone_safe_revealed[key]
            if total > 0 and revealed < total:
                zone_remaining[key] = total - revealed
            else:
                zone_remaining[key] = None

        if not zone_remaining:
            return prob_map

        valid_remaining = [v for v in zone_remaining.values() if v is not None and v > 0]
        if not valid_remaining:
            return prob_map

        min_remaining = min(valid_remaining)

        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            zr = r // zone_h
            zc = c // zone_w
            key = (zr, zc)
            rem = zone_remaining.get(key)
            if rem is not None and rem == min_remaining:
                adjusted[pos] = p * 0.85
            else:
                adjusted[pos] = p

        return adjusted

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = game.get_config().rows
        cols = game.get_config().cols
        zone_h = rows // 4
        zone_w = cols // 4
        zr = r // zone_h
        zc = c // zone_w

        zone_safe_total = 0
        zone_safe_revealed = 0
        for rr in range(zr * zone_h, min((zr + 1) * zone_h, rows)):
            for cc in range(zc * zone_w, min((zc + 1) * zone_w, cols)):
                cell = grid[rr][cc]
                if not cell.is_mine:
                    zone_safe_total += 1
                    if cell.is_revealed:
                        zone_safe_revealed += 1

        zone_remaining = zone_safe_total - zone_safe_revealed if zone_safe_total > 0 else 999

        return (p, zone_remaining, self._rng.random())

class VonNeumannCountMinesAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        return game.board.neighbors(r, c)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        neighbors = neighbors_of.get((r, c), [])
        unrevealed_neighbors = sum(
            1 for nr, nc in neighbors
            if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged
        )
        constrained_neighbors = sum(
            1 for nr, nc in neighbors
            if grid[nr][nc].is_revealed and grid[nr][nc].adjacent_mines is not None
        )
        sparsity_bonus = unrevealed_neighbors / max(len(neighbors), 1)
        constraint_bonus = constrained_neighbors / max(len(neighbors), 1)
        return (p - 0.1 * constraint_bonus + 0.05 * sparsity_bonus, unrevealed_neighbors, self._rng.random())

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        updated = dict(prob_map)
        for pos, p in prob_map.items():
            r, c = pos
            neighbors = neighbors_of.get((r, c), [])
            revealed_neighbors = [
                (nr, nc) for nr, nc in neighbors
                if grid[nr][nc].is_revealed and grid[nr][nc].adjacent_mines is not None
            ]
            if not revealed_neighbors:
                continue
            min_clue_remaining = None
            for nr, nc in revealed_neighbors:
                clue = grid[nr][nc].adjacent_mines
                cell_neighbors = neighbors_of.get((nr, nc), [])
                flagged = sum(1 for ar, ac in cell_neighbors if grid[ar][ac].is_flagged or (ar, ac) in mine_set)
                unrevealed = [ap for ap in cell_neighbors if not grid[ap[0]][ap[1]].is_revealed and ap not in mine_set and not grid[ap[0]][ap[1]].is_flagged]
                remaining = clue - flagged
                if len(unrevealed) > 0:
                    local_p = remaining / len(unrevealed)
                    local_p = max(0.0, min(1.0, local_p))
                    if min_clue_remaining is None or local_p < min_clue_remaining:
                        min_clue_remaining = local_p
            if min_clue_remaining is not None:
                updated[pos] = min(p, min_clue_remaining) if min_clue_remaining < p else p
        return updated

