class RookNeighborhood(Neighborhood):
    """Adjacency defined by rook-style moves: all cells sharing the same row
    or column within a fixed range of 3 steps. Each clue encodes long-range
    linear constraints (up to 6 cells per axis) that a skilled constraint
    solver can triangulate precisely using row/column elimination, while
    random play cannot interpret the extended linear clue regions."""

    _OFFSETS = [
        (-3, 0), (-2, 0), (-1, 0),
        ( 1, 0), ( 2, 0), ( 3, 0),
        (0, -3), (0, -2), (0, -1),
        (0,  1), (0,  2), (0,  3),
    ]

    def offsets(self) -> list[tuple[int, int]]:
        return self._OFFSETS

    def summary(self) -> dict:
        return {"offsets": list(self.offsets()), "style": "rook-range-3"}

