class RookRange3CheckerboardAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def neighbor_positions(self, game, r, c, rows, cols):
        offsets = [
            (-3, 0), (-2, 0), (-1, 0),
            ( 1, 0), ( 2, 0), ( 3, 0),
            (0, -3), (0, -2), (0, -1),
            (0,  1), (0,  2), (0,  3),
        ]
        result = []
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc))
        return result

    def opening_action(self, game, grid, rows, cols):
        cr, cc = rows // 2, cols // 2
        target_parity = (cr + cc) % 2
        best = None
        best_dist = float('inf')
        for r in range(rows):
            for c in range(cols):
                if (r + c) % 2 == target_parity:
                    dist = abs(r - cr) + abs(c - cc)
                    if dist < best_dist:
                        best_dist = dist
                        best = (r, c)
        if best is not None:
            return ('reveal', best[0], best[1])
        return ('reveal', cr, cc)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        parity_mine_count = {0: 0, 1: 0}
        parity_total = {0: 0, 1: 0}
        rows = game.get_config().rows
        cols = game.get_config().cols
        for r in range(rows):
            for c in range(cols):
                p = (r + c) % 2
                parity_total[p] += 1
                if (r, c) in mine_set:
                    parity_mine_count[p] += 1
        for pos, prob in list(prob_map.items()):
            r, c = pos
            p = (r + c) % 2
            if parity_total[p] > 0:
                density = parity_mine_count[p] / parity_total[p]
                if density > 0.0:
                    adjusted = min(1.0, prob * (1.0 + 0.1 * density))
                    prob_map[pos] = adjusted
        return prob_map

class ZoneConquestPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed)
        self._zone_rows = 4
        self._zone_cols = 4

    def _get_zones(self, rows, cols):
        zone_h = max(1, rows // self._zone_rows)
        zone_w = max(1, cols // self._zone_cols)
        zones = []
        r = 0
        while r < rows:
            c = 0
            while c < cols:
                cells = []
                for dr in range(zone_h):
                    for dc in range(zone_w):
                        cells.append((r + dr, c + dc))
                zones.append(cells)
                c += zone_w
            r += zone_h
        return zones

    def _zone_scores(self, game, grid, rows, cols):
        zones = self._get_zones(rows, cols)
        scores = {}
        for zone_cells in zones:
            valid = [(r, c) for (r, c) in zone_cells if 0 <= r < rows and 0 <= c < cols]
            safe_cells = [(r, c) for (r, c) in valid if not grid[r][c].is_mine]
            if not safe_cells:
                continue
            revealed = sum(1 for (r, c) in safe_cells if grid[r][c].is_revealed)
            total = len(safe_cells)
            fraction_revealed = revealed / total if total > 0 else 1.0
            if fraction_revealed >= 1.0:
                continue
            for (r, c) in valid:
                scores[(r, c)] = fraction_revealed
        return scores

    def _best_zone_cell(self, game, grid, rows, cols):
        zones = self._get_zones(rows, cols)
        best_zone = None
        best_fraction = 2.0
        for zone_cells in zones:
            valid = [(r, c) for (r, c) in zone_cells if 0 <= r < rows and 0 <= c < cols]
            safe_cells = [(r, c) for (r, c) in valid if not grid[r][c].is_mine]
            if not safe_cells:
                continue
            revealed = sum(1 for (r, c) in safe_cells if grid[r][c].is_revealed)
            total = len(safe_cells)
            fraction_revealed = revealed / total if total > 0 else 1.0
            if fraction_revealed >= 1.0:
                continue
            if fraction_revealed < best_fraction:
                best_fraction = fraction_revealed
                best_zone = valid
        return best_zone

    def opening_action(self, game, grid, rows, cols):
        zones = self._get_zones(rows, cols)
        mid_zone = zones[len(zones) // 2]
        candidates = [(r, c) for (r, c) in mid_zone if 0 <= r < rows and 0 <= c < cols]
        if candidates:
            r, c = candidates[len(candidates) // 2]
            return ("reveal", r, c)
        return ("reveal", rows // 2, cols // 2)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        rows = game.get_config().rows
        cols = game.get_config().cols
        zone_scores = self._zone_scores(game, grid, rows, cols)
        zone_fraction = zone_scores.get((r, c), 1.0)
        best_zone = self._best_zone_cell(game, grid, rows, cols)
        in_best_zone = 1 if (best_zone and (r, c) in best_zone) else 0
        return (p - 0.3 * in_best_zone + 0.1 * zone_fraction, -in_best_zone, self._rng.random())

