class StarNeighborhood(Neighborhood):
    """Combines the 4 orthogonal immediate neighbors with the 4 cells that are
    exactly 2 steps away orthogonally (a 'star' or 'plus-2' pattern), creating
    a sparse but long-range 8-neighbor topology. Each clue encodes constraints
    about cells one AND two steps away, letting a skilled solver build
    non-local inference chains while random play cannot exploit the gap."""

    _OFFSETS = [
        (-1, 0), (1, 0), (0, -1), (0, 1),   # immediate orthogonal
        (-2, 0), (2, 0), (0, -2), (0, 2),   # far orthogonal (skip one)
    ]

    def offsets(self) -> list[tuple[int, int]]:
        return self._OFFSETS

    def summary(self) -> dict:
        return {
            "topology": "star / orthogonal-plus-2",
            "immediate_neighbors": [(-1,0),(1,0),(0,-1),(0,1)],
            "far_neighbors": [(-2,0),(2,0),(0,-2),(0,2)],
            "note": "8 neighbors: 4 adjacent + 4 two-step orthogonal; creates skipped-cell long-range constraints"
        }

