class ParityAwareMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        updated = dict(prob_map)

        revealed_frontier = [
            (r, c)
            for r in range(rows)
            for c in range(cols)
            if grid[r][c].is_revealed and not grid[r][c].is_mine
        ]

        for r, c in revealed_frontier:
            clue = self.clue_value(game, grid, r, c)
            if clue is None:
                continue
            nbrs = neighbors_of.get((r, c), [])
            unknown_nbrs = [
                pos for pos in nbrs
                if not grid[pos[0]][pos[1]].is_revealed and not grid[pos[0]][pos[1]].is_flagged
            ]
            flagged_count = sum(
                1 for pos in nbrs
                if grid[pos[0]][pos[1]].is_flagged or pos in mine_set
            )
            remaining = clue - flagged_count
            n = len(unknown_nbrs)
            if n == 0:
                continue
            if remaining < 0:
                remaining = 0
            if remaining > n:
                remaining = n
            parity = remaining % 2
            if n == 1:
                pos = unknown_nbrs[0]
                if pos not in mine_set:
                    updated[pos] = float(remaining)
                continue
            if remaining == 0:
                for pos in unknown_nbrs:
                    if pos not in mine_set:
                        updated[pos] = min(updated.get(pos, 0.5), 0.05)
            elif remaining == n:
                for pos in unknown_nbrs:
                    if pos not in mine_set:
                        updated[pos] = max(updated.get(pos, 0.5), 0.95)
            else:
                base_prob = remaining / n
                for pos in unknown_nbrs:
                    if pos not in mine_set:
                        cur = updated.get(pos, 0.5)
                        blended = (cur + base_prob) / 2.0
                        updated[pos] = blended

        return updated

class DriftingMinesFlagFirstAgent(ArchiveAwarePAFGAgent):
