class ParityAwarePAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0])

        parity_map = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed and not cell.is_mine:
                    true_count = cell.adjacent_mines
                    parity_map[(r, c)] = true_count % 2

        changed = True
        iterations = 0
        while changed and iterations < 5:
            changed = False
            iterations += 1
            for (r, c), parity in parity_map.items():
                nbrs = neighbors_of.get((r, c), [])
                unknown = [pos for pos in nbrs if pos not in mine_set and not grid[pos[0]][pos[1]].is_revealed and not grid[pos[0]][pos[1]].is_flagged]
                flagged_count = sum(1 for pos in nbrs if pos in mine_set or grid[pos[0]][pos[1]].is_flagged)
                if len(unknown) == 0:
                    continue
                remaining_parity = (parity - flagged_count) % 2
                if len(unknown) == 1:
                    pos = unknown[0]
                    inferred = float(remaining_parity)
                    old = prob_map.get(pos, 0.5)
                    new_val = inferred
                    if abs(new_val - old) > 0.01:
                        prob_map[pos] = new_val
                        changed = True
                elif len(unknown) == 2:
                    p0 = unknown[0]
                    p1 = unknown[1]
                    est0 = prob_map.get(p0, 0.5)
                    est1 = prob_map.get(p1, 0.5)
                    if remaining_parity == 0:
                        combined = est0 * (1.0 - est1) + (1.0 - est0) * est1
                        if combined > 0.01:
                            scale = (1.0 - combined)
                            new0 = est0 * est1 / (1.0 - combined + 1e-9) + est0 * (1.0 - est1) * 0.0
                            new0 = (est0 * est1 + (1.0 - est0) * (1.0 - est1)) * est0 / max(est0 * est1 + (1.0 - est0) * (1.0 - est1), 1e-9)
                            new0 = min(max(new0, 0.0), 1.0)
                            if abs(new0 - est0) > 0.02:
                                prob_map[p0] = new0
                                changed = True
                    else:
                        new0 = (est0 * (1.0 - est1) + (1.0 - est0) * est1)
                        new0 = est0 * (1.0 - est1) / max(est0 * (1.0 - est1) + (1.0 - est0) * est1, 1e-9)
                        new0 = min(max(new0, 0.0), 1.0)
                        if abs(new0 - est0) > 0.02:
                            prob_map[p0] = new0
                            changed = True

        for pos in list(prob_map.keys()):
            if prob_map[pos] < 0.05:
                prob_map[pos] = 0.0
            elif prob_map[pos] > 0.95:
                prob_map[pos] = 1.0

        return prob_map

class ParityDriftingMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows else 0
        changed = True
        iterations = 0
        max_iterations = 10
        while changed and iterations < max_iterations:
            changed = False
            iterations += 1
            for r in range(rows):
                for c in range(cols):
                    cell = grid[r][c]
                    if not cell.is_revealed or cell.is_mine:
                        continue
                    true_count = cell.adjacent_mines
                    parity = true_count % 2
                    nbrs = neighbors_of.get((r, c), [])
                    flagged_count = sum(1 for nr, nc in nbrs if grid[nr][nc].is_flagged)
                    known_mines = sum(1 for nr, nc in nbrs if (nr, nc) in mine_set and not grid[nr][nc].is_flagged)
                    unknown = [(nr, nc) for nr, nc in nbrs
                               if not grid[nr][nc].is_revealed
                               and not grid[nr][nc].is_flagged
                               and (nr, nc) not in mine_set]
                    total_known_mines = flagged_count + known_mines
                    remaining_parity = (parity - (total_known_mines % 2)) % 2
                    if len(unknown) == 0:
                        continue
                    if len(unknown) == 1:
                        pos = unknown[0]
                        if remaining_parity == 1:
                            if pos not in mine_set:
                                mine_set.add(pos)
                                prob_map[pos] = 1.0
                                changed = True
                        else:
                            if prob_map.get(pos, 0.5) > 0.0:
                                prob_map[pos] = 0.0
                                changed = True
                    else:
                        if remaining_parity == 0:
                            for pos in unknown:
                                old = prob_map.get(pos, 0.5)
                                new_val = max(0.0, min(old, 0.45))
                                if abs(new_val - old) > 0.01:
                                    prob_map[pos] = new_val
                                    changed = True
                        else:
                            for pos in unknown:
                                old = prob_map.get(pos, 0.5)
                                new_val = max(old, 0.55)
                                if abs(new_val - old) > 0.01:
                                    prob_map[pos] = new_val
                                    changed = True
        return prob_map
